import csv
import io
import re

def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    if not records:
        return {"columns": [], "rows": []}

    def populated(row):
        return sum(bool(cell.strip()) for cell in row)

    def header_score(row):
        patterns = (
            r"\bname\b",
            r"\bdate\b",
            r"\bdestination\b",
            r"\bpurpose\b",
            r"\bcost\b",
            r"\bnumber\b",
            r"\bdescription\b",
            r"\bdepartment\b",
        )
        return sum(
            any(re.search(pattern, cell, re.IGNORECASE) for pattern in patterns)
            for cell in row
        )

    candidates = [i for i, row in enumerate(records) if populated(row) >= 3]
    if candidates:
        header_index = candidates[0]
        if populated(records[header_index]) <= 3:
            for i in candidates:
                if i >= header_index + 30:
                    break
                if header_score(records[i]) >= 2:
                    header_index = i
                    break
    else:
        candidates = [i for i, row in enumerate(records) if populated(row) >= 2]
        if candidates:
            header_index = candidates[0]
        else:
            nonempty = [i for i, row in enumerate(records) if populated(row)]
            if not nonempty:
                return {"columns": [], "rows": []}
            header_index = nonempty[0]

    header = records[header_index]
    data = records[header_index + 1:]
    width = max([7, len(header)] + [len(row) for row in data])

    columns = [cell.strip() for cell in header]
    existing = set(columns)
    for i in range(len(columns), width):
        name = "column_{}".format(i + 1)
        while name in existing:
            name += "_"
        columns.append(name)
        existing.add(name)

    rows = [row + [""] * (width - len(row)) for row in data]
    return {"columns": columns, "rows": rows}
